address constant CURVE_USDAF_POOL = 0x95591348FE9718bE8bfa3afcC9b017D9Ec18A7fa;
address constant TROVE_MANAGER = 0xa0290af48d2E43162A1a05Ab9d01a4ca3a8B60CB;
